cd /app; python3 - <<'EOF'
import numpy as np, csv, json
R=np.load('/tmp/R.npy')  # N,D,log10lr*,minloss,curv
N,D,L=R[:,0],R[:,1],R[:,3]
# Chinchilla fit: L = E + A N^-a + B D^-b  via grid on a,b + linear lstsq
best=None
for a in np.linspace(0.1,1.0,91):
  for b in np.linspace(0.1,1.0,91):
    X=np.c_[np.ones(len(N)),N**-a,D**-b]
    cf,rs,_,_=np.linalg.lstsq(X,L,rcond=None)
    if cf[1]<0 or cf[2]<0: continue
    rss=np.sum((X@cf-L)**2)
    if best is None or rss<best[0]: best=(rss,a,b,cf)
rss,a,b,cf=best
print("chinchilla fit a=%.3f b=%.3f E=%.3f A=%.3g B=%.3g rss=%.2e"%(a,b,cf[0],cf[1],cf[2],rss))
X=np.c_[np.ones(len(N)),N**-a,D**-b]; print("resid",np.round(X@cf-L,4))
def LP(n,d): return cf[0]+cf[1]*n**-a+cf[2]*d**-b
for d in [2e10,2e11,1e12]: print("N=1e9 D=%.0e L=%.4f"%(d,LP(1e9,d)))
# profile near-best fits to see extrapolation spread
alts=[]
for a2 in np.linspace(0.1,1.0,91):
  for b2 in np.linspace(0.1,1.0,91):
    X2=np.c_[np.ones(len(N)),N**-a2,D**-b2]; c2,_,_,_=np.linalg.lstsq(X2,L,rcond=None)
    if c2[1]<0 or c2[2]<0: continue
    r2=np.sum((X2@c2-L)**2)
    if r2<2*rss: alts.append((r2,a2,b2,c2[0]+c2[1]*1e9**-a2+c2[2]*1e12**-b2))
alts=np.array(alts); print("near-best fits: n=%d, L(1e9,1e12) range %.3f..%.3f"%(len(alts),alts[:,3].min(),alts[:,3].max()))
# pooled lr-sensitivity shape
pts={}
for r in csv.DictReader(open('notebook/runs.csv')):
    pts.setdefault((float(r['N']),float(r['D'])),[]).append((float(r['lr']),float(r['loss'])))
for l in open('lab_runs.jsonl'):
    x=json.loads(l); c=x.get('config',x)
    if x.get('status')=='ok': pts.setdefault((c['N'],c['D']),[]).append((c['lr'],x['loss']))
off=[];exc=[]
for (n,d),p in pts.items():
    row=R[(R[:,0]==n)&(R[:,1]==d)][0]
    for lr,ls in p: off.append(np.log10(lr)-row[2]); exc.append(ls-row[3])
off=np.array(off);exc=np.array(exc); o=np.argsort(off)
for i in o: print("%+.2f %.4f"%(off[i],exc[i]))
# fit high side excess as quadratic+cubic for off in [0,0.7]
m=(off>-0.05)&(off<0.75); c=np.polyfit(off[m],exc[m],3); 
print("excess at +0.357:",np.polyval(c,0.357), " at +0.30..+0.42:",[round(np.polyval(c,t),4) for t in (0.30,0.357,0.42)])
